  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'វឌ្ឍនភាពនៃការចាក់សារថ្មី ស្ថានភាពមើលពេលក្រោយ ការចូលចិត្ត មតិយោបល់ ការជាវ ការជូនដំណឹង និងការវិភាគអ្នកគ្រប់គ្រងត្រូវបានរក្សាទុកក្នុងមូលដ្ឋានទិន្នន័យ នៅពេលភ្ជាប់ទៅលក្ខណៈពិសេសវេទិកាដែលបានផ្ទៀងផ្ទាត់។',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'ការចាក់សារថ្មី មតិយោបល់ ការចូលចិត្ត មើលពេលក្រោយ ការជាវ ការជូនដំណឹង សារ បញ្ជីចាក់ និងការកំណត់ភាសាអាចរកបានតាមរយៈម៉ឺនុយរុករក និងគណនីចម្បង។',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub គឺជាវេទិកាវីដេអូសម្រាប់ការបង្ហោះ ការមើល ការកំណត់កាលវិភាគ ការគ្រប់គ្រង និងសម្របសម្រួលមាតិកាអ្នកបង្កើតពីគណនីមួយ។',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub គឺជាវេទិកាវីដេអូដែលកំពុងដំណើរការលើការដាក់ពង្រាយនេះ ដែលបង្កើតឡើងសម្រាប់អ្នកបង្កើត អ្នកមើល សហគមន៍ និងប្រតិបត្តិករវេទិកា។',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub ផ្តល់នូវបណ្តាញអ្នកបង្កើត ការបង្ហោះវីដេអូ ការបោះពុម្ពដែលបានកំណត់ពេល ការជាវ មតិយោបល់ បញ្ជីចាក់ មើលពេលក្រោយ ទំព័រមាតិកាបន្តផ្ទាល់ និងឧបករណ៍គ្រប់គ្រងពីវេទិកាមួយ។',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub ប្រើប្រាស់ខូគី និងឃ្លាំងផ្ទុកកម្មវិធីរុករកតាមអ៊ីនធឺណិតសំខាន់ៗសម្រាប់វគ្គចូល ការផ្ទៀងផ្ទាត់ API ឥរិយាបថ CSRF/សុវត្ថិភាព ការជ្រើសរើសភាសា ការជ្រើសរើសប្រធានបទ ស្ថានភាពម៉ឺនុយគណនី និងលក្ខណៈពិសេសផ្សេងទៀតដែលត្រូវការសម្រាប់កម្មវិធីដើម្បីដំណើរការ។',
  'playhub_language, theme' => 'playhub_language ប្រធានបទ',
