  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'ឯកជនភាព ខូគី សុវត្ថិភាពគណនី សារជំនួយ និងទិន្នន័យសម្របសម្រួលត្រូវបានគ្រប់គ្រងតាមរយៈគោលការណ៍ និងកំណត់ត្រាផ្នែកខាងក្រោយដែលភ្ជាប់ទៅ PlayHub ។',
