  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'ការគ្រប់គ្រងការសងប្រាក់វិញត្រូវបានចងភ្ជាប់ទៅនឹងកំណត់ត្រាវិក្កយបត្រពិតប្រាកដ និងការពិនិត្យមើលអ្នកគ្រប់គ្រង។ ប្រសិនបើការចេញវិក្កយបត្រមិនត្រូវបានកំណត់រចនាសម្ព័ន្ធសម្រាប់ការដាក់ឱ្យប្រើប្រាស់នេះទេ វាមិនមានការគិតថ្លៃលើវេទិកាដើម្បីសងប្រាក់វិញទេ។',
