  'Stores language, theme, and interface preferences.' => 'រក្សាទុកភាសា រូបរាង និងចំណូលចិត្តចំណុចប្រទាក់។',
  'Studio, playlists, analytics, channels.' => 'ស្ទូឌីយោ បញ្ជីចាក់ ការវិភាគ ប៉ុស្តិ៍។',
  'Submit a billing or refund message to admin support.' => 'ដាក់ស្នើការចេញវិក្កយបត្រ ឬសារសងប្រាក់ទៅផ្នែកជំនួយអ្នកគ្រប់គ្រង។',
