  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'កំណត់សម្គាល់បច្ចេកទេសសម្រាប់ការរួមបញ្ចូលជាមួយ PlayHub API បច្ចុប្បន្ន និងដំណើរការការងារបង្ហោះ។',
  'Tell us more about your question or request...' => 'ប្រាប់យើងបន្ថែមអំពីសំណួរ ឬសំណើរបស់អ្នក...',
