  'The configured' => 'ដែលបានកំណត់រចនាសម្ព័ន្ធ',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ទំព័រអ្នកអភិវឌ្ឍន៍ត្រូវបានភ្ជាប់ទៅផ្នែកខាងក្រោយ Laravel ផ្ទាល់៖ បញ្ជីសារពើភណ្ឌផ្លូវ ការរាប់មូលដ្ឋានទិន្នន័យ ដែនកំណត់ផ្ទុកឡើង និងទិន្នន័យមេតានៃវេទិកាត្រូវបានផ្ទុកពី /api/developers ។',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ផ្នែកខាងមុខផ្ទុកនូវចំណូលចិត្តដូចជាភាសា រចនាប័ទ្មដែលបានជ្រើសរើស ជួរចាក់សារថ្មី ការមើលដំណើរការ និងស្ថានភាពចំណុចប្រទាក់ ដូច្នេះបទពិសោធន៍នៅតែមានភាពស៊ីសង្វាក់គ្នាលើការរុករកទំព័រ និងការផ្ទុកឡើងវិញ។',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'ការងារ​ដំណើរការ​បាន​អ៊ិនកូដ​ការ​បង្ហាញ បង្កើត​រូបភាពតូចៗ​នៅពេល​ចាំបាច់ រក្សាទុក​ចំណងជើង និង​សម្គាល់​វីដេអូ​រួចរាល់​នៅពេល​ដំណើរការ​បញ្ចប់។ វីដេអូដែលបានកំណត់ពេលអនាគតនៅតែជាឯកជនរហូតដល់អ្នកកំណត់ពេលចេញផ្សាយពួកគេ។',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'ប្រព័ន្ធផ្ទុកឡើងត្រូវបានគាំទ្រដោយមូលដ្ឋានទិន្នន័យ គាំទ្រប្រភេទ និងភាសាពី API ដំណើរការវីដេអូដែលបានបង្ហោះ រក្សាទុករូបភាពតូចៗ និងចំណងជើង និងរក្សាមាតិកាដែលបានកំណត់ពេលទុកជាឯកជនរហូតដល់ពេលចេញផ្សាយរបស់វា។',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'ទំព័រនេះពន្យល់ពីរបៀបដែល PlayHub ប្រើប្រាស់ខូគី និងការផ្ទុកកម្មវិធីរុករកតាមអ៊ីនធឺណិតសម្រាប់វគ្គ សុវត្ថិភាព ចំណូលចិត្ត ការចាក់សារថ្មី និងមុខងារដែលបានផ្ទៀងផ្ទាត់។',
  'Ticket source' => 'ប្រភពសំបុត្រ',
