  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'បង្ហោះ មើល ជាវ សម្របសម្រួល និងបង្កើតជាមួយទិន្នន័យ PlayHub ផ្ទាល់។',
  'Uploaded videos' => 'វីដេអូដែលបានបង្ហោះ',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'វីដេអូ​ដែល​បាន​បង្ហោះ​ត្រូវ​បាន​អ៊ិនកូដ​ទៅ​ក្នុង​ការ​បង្ហាញ​ដែល​អាច​លេង​បាន។ ពេលវេលាដំណើរការអាស្រ័យលើទំហំឯកសារ រយៈពេល ការផ្ទុកម៉ាស៊ីនមេ និងស្ថានភាពជួរ។ ទំព័រផ្ទុកឡើង និង Creator Studio បង្ហាញស្ថានភាពដំណើរការពិតប្រាកដពីកំណត់ត្រាវីដេអូ។',
  'Uploads, scheduling, and processing are available.' => 'ការអាប់ឡូត កាលវិភាគ និងដំណើរការមាន។',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'ប្រើ /api/videos ចំណុចបញ្ចប់របស់ប៉ុស្តិ៍ និងផ្លូវដែលផ្ទៀងផ្ទាត់សម្រាប់លំហូរការងាររបស់អ្នកបង្កើត។',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'ប្រើសកម្មភាពរបាយការណ៍ដែលភ្ជាប់មកជាមួយសម្រាប់វីដេអូ និងមតិ ដូច្នេះអ្នកគ្រប់គ្រងទទួលបានឯកសារយោងខ្លឹមសារពិតប្រាកដ។ ទំព័រផ្ទាំងគ្រប់គ្រងគ្រប់គ្រងប្រើប្រាស់ទិន្នន័យមូលដ្ឋានទិន្នន័យផ្ទាល់សម្រាប់អ្នកប្រើប្រាស់ ខ្លឹមសារ របាយការណ៍ ការរកប្រាក់ ការវិភាគ ការគាំទ្រ តួនាទី និងការកំណត់ប្រព័ន្ធ។',
  'Use Contact Us' => 'ប្រើទំនាក់ទំនងយើងខ្ញុំ',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'ប្រើ JSON សម្រាប់សំណើ API ធម្មតា និង FormData សម្រាប់ការបង្ហោះឯកសារ។ កុំរំលងការបញ្ជាក់៖ ប្រភេទ និងភាសាគឺជាលេខសម្គាល់មូលដ្ឋានទិន្នន័យ ភាពមើលឃើញត្រូវបានកំណត់ចំពោះសាធារណៈ មិនបានរាយបញ្ជី ឬឯកជន ហើយចំណងជើងទទួលយកឯកសារ SRT, VTT ឬ TXT ។',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'ប្រើការកំណត់ដើម្បីធ្វើបច្ចុប្បន្នភាពប្រវត្តិរូប សុវត្ថិភាព ពាក្យសម្ងាត់ ការដឹកជញ្ជូនកត្តាពីរ ឧបករណ៍ ចំណូលចិត្ត និងជម្រើសការជូនដំណឹងរបស់អ្នក។ ប្រសិនបើអ្នកមិនអាចចូលប្រើគណនីរបស់អ្នកបានទេ សូមប្រើលំហូរចូល និងផ្តល់អ៊ីមែលគណនីទៅអ្នកគ្រប់គ្រងគេហទំព័រ។',
  'Use the contact form' => 'ប្រើទម្រង់ទំនាក់ទំនង',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ប្រើសកម្មភាពរបាយការណ៍លើវីដេអូ មតិយោបល់ និងការបង្ហោះសហគមន៍ ដូច្នេះអ្នកគ្រប់គ្រងទទួលបានឯកសារយោងខ្លឹមសារពិតប្រាកដ។',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'ប្រើសកម្មភាពរបាយការណ៍នៅលើវីដេអូ មតិយោបល់ និងការបង្ហោះសហគមន៍ នៅពេលដែលមាតិកាអាចបំពានច្បាប់វេទិកា។ របាយការណ៍ទាំងនេះត្រូវបានចងភ្ជាប់ទៅនឹងកំណត់ត្រាខ្លឹមសារពិត ហើយប្រសើរជាងសារទូទៅ ពីព្រោះអ្នកគ្រប់គ្រងអាចពិនិត្យមើលធាតុពិតប្រាកដ។',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'ប្រើឆានែល PlayHub ត្រឹមត្រូវសម្រាប់ជំនួយគណនី របាយការណ៍ខ្លឹមសារ បញ្ហាបច្ចេកទេស និងសំណើអ្នកគ្រប់គ្រង។',
  'Video categories' => 'ប្រភេទវីដេអូ',
  'Video for everyone. Built for creators and viewers.' => 'វីដេអូសម្រាប់អ្នករាល់គ្នា។ បង្កើតឡើងពីទិន្នន័យវេទិកាពិត។',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ការបង្ហោះវីដេអូ ការកំណត់កាលវិភាគ រូបភាពតូច និងបញ្ហាដំណើរការ។',
  'Videos, thumbnails, captions, processing.' => 'វីដេអូ រូបភាពតូចៗ ចំណងជើង ដំណើរការ។',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'អ្នកមើលអាចរកមើលប្រភេទ ស្វែងរកវីដេអូ មើលមាតិកា ជាវប៉ុស្តិ៍ រក្សាទុកវីដេអូដើម្បីមើលពេលក្រោយ ផ្តល់មតិ ទទួលការជូនដំណឹង និងគ្រប់គ្រងចំណូលចិត្តភាសា និងភាពងាយស្រួល។',
  'Viewing and community help' => 'ការមើល និងការជួយសហគមន៍',
  'Waiting for backend endpoint inventory.' => 'កំពុងរង់ចាំបញ្ជីសារពើភណ្ឌចំណុចបញ្ចប់នៅខាងក្រោយ។',
  'We’re here to help.' => 'យើងនៅទីនេះដើម្បីជួយ។',
  'What is PlayHub?' => 'តើ PlayHub ជាអ្វី?',
  'What PlayHub does' => 'អ្វីដែល PlayHub ធ្វើ',
  'Where do contact messages go?' => 'តើសារទំនាក់ទំនងទៅណា?',
  'Why is my video still processing?' => 'ហេតុអ្វីបានជាវីដេអូរបស់ខ្ញុំនៅតែដំណើរការ?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'បាទ។ ប្រើវាលកាលបរិច្ឆេទ និងពេលវេលាដើមនៅលើទំព័រផ្ទុកឡើង។ កម្មវិធីខាងក្រោយផ្ទុកកាលវិភាគ (schedule_at) ដំណើរការវីដេអូ រក្សាវាទុកជាឯកជនខណៈពេលដែលកាលបរិច្ឆេទគឺនាពេលអនាគត ហើយចេញផ្សាយវានៅពេលដែលអ្នកកំណត់ពេល Laravel ដំណើរការបន្ទាប់ពីពេលវេលាដែលបានកំណត់។',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'បាទ។ ប្រើវាលកាលវិភាគដើមនៅលើការបង្ហោះ។ កម្មវិធីខាងក្រោយរក្សាទុកកម្មវិធី Scheded_at និងចេញផ្សាយវីដេអូបន្ទាប់ពីដំណើរការនៅពេលដែលដល់ម៉ោងកំណត់។',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'អ្នកកំពុងរកមើលជាភ្ញៀវ។ ចូលដើម្បីចូលប្រើឧបករណ៍ជាក់លាក់គណនី។',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'អ្នកទទួលខុសត្រូវចំពោះព័ត៌មានសម្ងាត់គណនីរបស់អ្នក សកម្មភាពកម្រងព័ត៌មាន មាតិកាដែលបានបង្ហោះ មតិយោបល់ សារ និងសកម្មភាពអ្នកបង្កើត ឬអ្នកគ្រប់គ្រងដែលបានអនុវត្តចេញពីគណនីរបស់អ្នក។ ប្រើពាក្យសម្ងាត់ខ្លាំង និងរក្សាវិធីសាស្ត្រចែកចាយកត្តាពីរបច្ចុប្បន្ន។',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'អ្នកអាចសម្អាតខូគីរបស់កម្មវិធីរុករកតាមអ៊ីនធឺណិត និងទំហំផ្ទុកក្នុងមូលដ្ឋាននៅក្នុងការកំណត់កម្មវិធីរុករករបស់អ្នក។ ការសម្អាតកន្លែងផ្ទុកសំខាន់អាចឱ្យអ្នកចេញពីគណនី កំណត់ចំណូលចិត្តភាសា/ស្បែកឡើងវិញ លុបស្ថានភាពចាក់សារថ្មីក្នុងមូលដ្ឋាន និងតម្រូវឱ្យអ្នកចូលម្តងទៀត។',
  'You receive a response by email.' => 'អ្នកទទួលបានការឆ្លើយតបតាមអ៊ីមែល។',
  'You’re in control' => 'អ្នកស្ថិតក្នុងការគ្រប់គ្រង',
  'Your choices' => 'ជម្រើសរបស់អ្នក។',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'សាររបស់អ្នកត្រូវបានរក្សាទុកដោយផ្ទាល់នៅក្នុងផ្នែកខាងក្រោយនៃគេហទំព័រ ហើយបង្ហាញនៅក្នុងផ្ទាំងគ្រប់គ្រងក្រោមផ្នែកជំនួយ។',
  'Your support' => 'ការគាំទ្ររបស់អ្នក។',
  'Watch video' => 'មើលវីដេអូ',
  'Copy link' => 'ចម្លងតំណ',
  'View creator' => 'មើលអ្នកបង្កើត',
  'Remove from playlist' => 'យកចេញពីបញ្ជីចាក់',
  'Removing videos from playlists is not available here yet.' => 'ការលុបវីដេអូចេញពីបញ្ជីចាក់មិនទាន់មាននៅទីនេះនៅឡើយទេ។',
  'Create New Playlist' => 'បង្កើតបញ្ជីចាក់ថ្មី។',
  'Organize your videos into a playlist' => 'រៀបចំវីដេអូរបស់អ្នកទៅក្នុងបញ្ជីចាក់',
  'Playlist Name' => 'ឈ្មោះបញ្ជីចាក់',
  'e.g. Travel Vlogs 2025' => 'ឧ. Vlogs ទេសចរណ៍ 2025',
  '(optional)' => '(ស្រេចចិត្ត)',
  'What’s this playlist about?' => 'តើបញ្ជីចាក់នេះនិយាយអំពីអ្វី?',
  'Select Color' => 'ជ្រើសរើសពណ៌',
  'This color will represent your playlist' => 'ពណ៌នេះនឹងតំណាងឱ្យបញ្ជីចាក់របស់អ្នក។',
  'Anyone can view this playlist' => 'នរណាម្នាក់អាចមើលបញ្ជីចាក់នេះបាន',
  'Only you can view this playlist' => 'មានតែអ្នកទេដែលអាចមើលបញ្ជីចាក់នេះបាន',
  'Anyone with the link can view' => 'អ្នកដែលមានតំណអាចមើលបាន។',
  'Add to Playlist' => 'បន្ថែមទៅបញ្ជីចាក់',
  'Add videos to this playlist now' => 'បញ្ចូលវីដេអូទៅក្នុងបញ្ជីចាក់នេះឥឡូវនេះ',
  'Search videos to add...' => 'ស្វែងរកវីដេអូដើម្បីបន្ថែម...',
  'selected' => 'បានជ្រើសរើស',
  'Clear' => 'ច្បាស់',
  'Tip' => 'ព័ត៌មានជំនួយ',
  'Use playlists to organize your content and make it easier for your audience to discover more videos.' => 'ប្រើបញ្ជីចាក់ដើម្បីរៀបចំមាតិការបស់អ្នក និងធ្វើឱ្យវាកាន់តែងាយស្រួលសម្រាប់ទស្សនិកជនរបស់អ្នកក្នុងការស្វែងរកវីដេអូបន្ថែមទៀត។',
  'Unable to create playlist.' => 'មិនអាចបង្កើតបញ្ជីចាក់បានទេ។',
  'public' => 'សាធារណៈ',
  'private' => 'ឯកជន',
