  'Cannot prepare imported video file.' => 'មិនអាចរៀបចំឯកសារវីដេអូដែលបាននាំចូលទេ។',
  'Cannot read remote video file.' => 'មិនអាចអានឯកសារវីដេអូពីចម្ងាយបានទេ។',
  'Imported video exceeds the maximum upload size.' => 'វីដេអូដែលបាននាំចូលលើសពីទំហំផ្ទុកអតិបរមា។',
  'Remote video file is empty.' => 'ឯកសារវីដេអូពីចម្ងាយគឺទទេ។',
  'Video import downloader command is not configured.' => 'ពាក្យបញ្ជាកម្មវិធីទាញយកវីដេអូនាំចូលមិនត្រូវបានកំណត់រចនាសម្ព័ន្ធទេ។',
  'Downloader did not create an importable video file.' => 'កម្មវិធីទាញយកមិនបានបង្កើតឯកសារវីដេអូដែលអាចនាំចូលបានទេ។',
  'Import URL is invalid.' => 'នាំចូល URL មិនត្រឹមត្រូវទេ។',
