  'Import URL does not match the selected provider.' => 'URL នាំចូលមិនត្រូវគ្នានឹងអ្នកផ្តល់សេវាដែលបានជ្រើសរើសទេ។',
  'Import URL host cannot be resolved.' => 'នាំចូល URL ម៉ាស៊ីនមិនអាចដោះស្រាយបានទេ។',
  'Import URL must resolve to a public host.' => 'នាំចូល URL ត្រូវតែដោះស្រាយទៅម៉ាស៊ីនសាធារណៈ។',
