  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'ជ្រើសរើសសេវាកម្មដែលបានបើក ហើយបិទភ្ជាប់ URL វីដេអូសាធារណៈ។ PlayHub នឹងទៅយកព័ត៌មានលម្អិត ហើយលេងវាពីអ្នកផ្តល់សេវាដើម។',
